// @FIGURE_CODE_BEGIN
var draw = SVG().addTo(document.getElementById('container')).size('100%', '100%');
var W = 900, H = 650;
draw.viewbox(0, 0, W, H);

var MAGENTA = '#e8007d', BLACK = '#111';

/* ---------- geometry state ---------- */
var O = { x: 95, y: 430 };
// four rays through O, directions (unnormalised, screen coords y-down)
var dirs = [
  { x: 1, y: 0.24 },   // ray 1 (lowest) — R-line is parallel to this one
  { x: 1, y: 0.055 },
  { x: 1, y: -0.14 },
  { x: 1, y: -0.36 }
];
// transversal lines (two anchor points each)
var Pline = { a: { x: 375, y: 520 }, b: { x: 392, y: 235 } };
var Qline = { a: { x: 565, y: 600 }, b: { x: 470, y: 215 } };
var Rpivot = { x: 470, y: 180 };   // R-line passes through here, parallel to ray 1

function cross(u, v) { return u.x * v.y - u.y * v.x; }
function sub(a, b) { return { x: a.x - b.x, y: a.y - b.y }; }
function add(a, b) { return { x: a.x + b.x, y: a.y + b.y }; }
function mul(a, s) { return { x: a.x * s, y: a.y * s }; }

function rayLine(o, d, a, b) {
  var ab = sub(b, a), ao = sub(a, o);
  var den = cross(d, ab);
  if (Math.abs(den) < 1e-9) return null;
  var t = cross(ao, ab) / den;
  return add(o, mul(d, t));
}
function lineParam(p, a, b) {
  var ab = sub(b, a);
  return (sub(p, a).x * ab.x + sub(p, a).y * ab.y) / (ab.x * ab.x + ab.y * ab.y);
}
function projectOnLine(p, a, b) {
  var t = lineParam(p, a, b);
  return add(a, mul(sub(b, a), t));
}
function crossRatio(ts) {
  var t1 = ts[0], t2 = ts[1], t3 = ts[2], t4 = ts[3];
  return ((t3 - t1) * (t4 - t2)) / ((t3 - t2) * (t4 - t1));
}

/* ---------- layers ---------- */
var gRays = draw.group(), gLines = draw.group(), gPts = draw.group(),
    gLab = draw.group(), gHud = draw.group();

var rayEls = [], ptEls = { P: [], Q: [], R: [] }, labEls = [];
var plineEl, qlineEl, rlineEl, oEl, oLab, infLab, infArrow;
var crText = [];

function serifText(x, y, size) {
  return draw.text('').font({ family: 'Georgia, "Times New Roman", serif', size: size, weight: 'bold' })
    .attr({ 'paint-order': 'stroke', stroke: '#fff', 'stroke-width': 4, 'stroke-linejoin': 'round' })
    .move(x, y);
}
function labelWithSub(x, y, base, sub_) {
  var t = serifText(x, y, 24);
  t.tspan(base);
  t.tspan(sub_).font({ size: 16 }).attr('dy', 6);
  return t;
}

function build() {
  var i;
  for (i = 0; i < 4; i++) rayEls.push(gRays.line(0, 0, 0, 0).stroke({ color: BLACK, width: 3 }));
  plineEl = gLines.line(0, 0, 0, 0).stroke({ color: MAGENTA, width: 3.5 });
  qlineEl = gLines.line(0, 0, 0, 0).stroke({ color: MAGENTA, width: 3.5 });
  rlineEl = gLines.line(0, 0, 0, 0).stroke({ color: MAGENTA, width: 3.5 });

  function mkDot(r, tip) {
    var c = gPts.circle(r * 2).fill(BLACK).css('cursor', 'grab');
    c.on('mousemove', function (e) { showTooltip(tip, e); })
     .on('mouseleave', function () { hideTooltip(); });
    return c;
  }
  for (i = 0; i < 4; i++) {
    ptEls.P.push(mkDot(11, 'P' + (i + 1) + ' — drag along the P-line'));
    ptEls.Q.push(mkDot(11, 'Q' + (i + 1) + ' — drag along the Q-line'));
    ptEls.R.push(mkDot(11, i === 0 ? 'R1 → ∞ (ray ∥ R-line)' : 'R' + (i + 1) + ' = ray ' + (i + 1) + ' ∩ R-line'));
  }
  oEl = gPts.circle(26).fill(BLACK).css('cursor', 'grab');
  oEl.on('mousemove', function (e) { showTooltip('O — projection center (drag me)', e); })
     .on('mouseleave', function () { hideTooltip(); });

  oLab = serifText(0, 0, 30); oLab.tspan('O');
  for (i = 0; i < 4; i++) {
    labEls.push(labelWithSub(0, 0, 'P', String(i + 1)));
    labEls.push(labelWithSub(0, 0, 'Q', String(i + 1)));
    labEls.push(labelWithSub(0, 0, 'R', String(i + 1)));
  }
  infLab = serifText(0, 0, 26);
  infLab.tspan('R'); infLab.tspan('1').font({ size: 17 }).attr('dy', 7);
  infLab.tspan(' → ∞').attr('dy', -7);
  infArrow = gHud.line(0, 0, 0, 0).stroke({ color: BLACK, width: 2 });

  var names = ['CR(P₁,P₂,P₃,P₄)', 'CR(Q₁,Q₂,Q₃,Q₄)', 'CR(R₁,R₂,R₃,R₄)'];
  for (i = 0; i < 3; i++) {
    var t = draw.text('').font({ family: 'Georgia, serif', size: 19 })
      .attr({ 'paint-order': 'stroke', stroke: '#fff', 'stroke-width': 5, 'stroke-linejoin': 'round' })
      .move(18, 16 + i * 27);
    t.tspan(names[i] + ' = ').fill(BLACK);
    t.tspan('').fill(MAGENTA).font({ weight: 'bold' });
    crText.push(t);
  }
}

function farEnd(d) { // end of ray far beyond viewbox
  return add(O, mul(d, 1500));
}

function update(highlightInf) {
  var i, p, q, r;
  var rdir = dirs[0];
  var Ra = Rpivot, Rb = add(Rpivot, rdir);

  // lines
  plineEl.plot(Pline.a.x, Pline.a.y, Pline.b.x, Pline.b.y);
  qlineEl.plot(Qline.a.x, Qline.a.y, Qline.b.x, Qline.b.y);
  var rEnd = add(Rpivot, mul(rdir, 620));
  rlineEl.plot(Ra.x - rdir.x * 120, Ra.y - rdir.y * 120, rEnd.x, rEnd.y);

  // rays
  for (i = 0; i < 4; i++) {
    var e = farEnd(dirs[i]);
    rayEls[i].plot(O.x, O.y, e.x, e.y);
  }

  // points
  var P = [], Q = [], R = [];
  for (i = 0; i < 4; i++) {
    P.push(rayLine(O, dirs[i], Pline.a, Pline.b));
    Q.push(rayLine(O, dirs[i], Qline.a, Qline.b));
    R.push(i === 0 ? null : rayLine(O, dirs[i], Ra, Rb));
  }
  oEl.center(O.x, O.y);
  oLab.move(O.x - 34, O.y - 14);

  for (i = 0; i < 4; i++) {
    ptEls.P[i].center(P[i].x, P[i].y).show();
    ptEls.Q[i].center(Q[i].x, Q[i].y).show();
    if (R[i]) { ptEls.R[i].center(R[i].x, R[i].y).show(); } else { ptEls.R[i].hide(); }
  }
  // labels: P left of P-line, Q right of Q-line, R above R-line
  var labOffP = [[16, 14], [16, 8], [16, -2], [16, -12]];
  var labOffQ = [[16, -34], [18, -16], [18, -14], [14, 2]];
  var labOffR = [[0, 0], [-14, -46], [-14, -52], [-14, -58]];
  for (i = 0; i < 4; i++) {
    labEls[i * 3].move(P[i].x + labOffP[i][0], P[i].y + labOffP[i][1]);
    labEls[i * 3 + 1].move(Q[i].x + labOffQ[i][0], Q[i].y + labOffQ[i][1]);
    if (R[i]) { labEls[i * 3 + 2].move(R[i].x + labOffR[i][0], R[i].y + labOffR[i][1]).show(); }
    else labEls[i * 3 + 2].hide();
  }

  // R1 → ∞ annotation at right end of ray 1
  var inf = add(O, mul(dirs[0], 720 / Math.hypot(dirs[0].x, dirs[0].y)));
  infLab.move(inf.x + 6, inf.y - 46)
    .fill(highlightInf ? MAGENTA : BLACK);
  infArrow.plot(inf.x - 34, inf.y - 20, inf.x - 4, inf.y - 8)
    .stroke({ color: highlightInf ? MAGENTA : BLACK });

  // cross-ratios
  function ts(pts, a, b) { return pts.map(function (p) { return lineParam(p, a, b); }); }
  var crP = crossRatio(ts(P, Pline.a, Pline.b));
  var crQ = crossRatio(ts(Q, Qline.a, Qline.b));
  var crR = crossRatio(ts([P[0], R[1], R[2], R[3]], Ra, Rb).map(function (t, i) { return t; })); // R1→∞
  // with R1 at infinity, CR = (t3-t2 cancelled) → use limit: ((t3-∞)/(t3-t2))/((t4-∞)/(t4-t2)) = (t4-t2)/(t3-t2)
  var tR = ts([R[1], R[2], R[3]], Ra, Rb);
  crR = (tR[2] - tR[0]) / (tR[1] - tR[0]);

  crText[0].children()[1].text(crP.toFixed(4));
  crText[1].children()[1].text(crQ.toFixed(4));
  crText[2].children()[1].text(crR.toFixed(4));
}

/* ---------- dragging ---------- */
var dragTarget = null;
function svgPoint(ev) {
  var pt = draw.node.createSVGPoint();
  pt.x = ev.clientX; pt.y = ev.clientY;
  var m = draw.node.getScreenCTM();
  return m ? pt.matrixTransform(m.inverse()) : { x: pt.x, y: pt.y };
}
ptEls.P.forEach(function (c, i) {
  c.on('pointerdown', function (e) { dragTarget = { kind: 'P', i: i }; e.preventDefault(); });
});
ptEls.Q.forEach(function (c, i) {
  c.on('pointerdown', function (e) { dragTarget = { kind: 'Q', i: i }; e.preventDefault(); });
});
oEl.on('pointerdown', function (e) { dragTarget = { kind: 'O' }; e.preventDefault(); });

window.addEventListener('pointermove', function (e) {
  if (!dragTarget) return;
  var p = svgPoint(e), np;
  if (dragTarget.kind === 'O') {
    O = { x: Math.max(10, Math.min(500, p.x)), y: Math.max(40, Math.min(H - 20, p.y)) };
  } else if (dragTarget.kind === 'P') {
    np = projectOnLine(p, Pline.a, Pline.b);
    dirs[dragTarget.i] = sub(np, O);
  } else {
    np = projectOnLine(p, Qline.a, Qline.b);
    dirs[dragTarget.i] = sub(np, O);
  }
  update(currentStep === 3);
});
window.addEventListener('pointerup', function () { dragTarget = null; });

