  var crQ = crossRatio(ts(Q, Qline.a, Qline.b));
  var crR = crossRatio(ts([P[0], R[1], R[2], R[3]], Ra, Rb).map(function (t, i) { return t; })); // R1→∞
  // with R1 at infinity, CR = (t3-t2 cancelled) → use limit: ((t3-∞)/(t3-t2))/((t4-∞)/(t4-t2)) = (t4-t2)/(t3-t2)
  var tR = ts([R[1], R[2], R[3]], Ra, Rb);
  crR = (tR[2] - tR[0]) / (tR[1] - tR[0]);

  crText[0].children()[1].text(crP.toFixed(4));
  crText[1].children()[1].text(crQ.toFixed(4));
  crText[2].children()[1].text(crR.toFixed(4));
}

/* ---------- dragging ---------- */
var dragTarget = null;
function svgPoint(ev) {
  var pt = draw.node.createSVGPoint();
  pt.x = ev.clientX; pt.y = ev.clientY;
  var m = draw.node.getScreenCTM();
  return m ? pt.matrixTransform(m.inverse()) : { x: pt.x, y: pt.y };
}
ptEls.P.forEach(function (c, i) {
  c.on('pointerdown', function (e) { dragTarget = { kind: 'P', i: i }; e.preventDefault(); });
});
ptEls.Q.forEach(function (c, i) {
  c.on('pointerdown', function (e) { dragTarget = { kind: 'Q', i: i }; e.preventDefault(); });
});
oEl.on('pointerdown', function (e) { dragTarget = { kind: 'O' }; e.preventDefault(); });

window.addEventListener('pointermove', function (e) {
  if (!dragTarget) return;
  var p = svgPoint(e), np;
  if (dragTarget.kind === 'O') {
    O = { x: Math.max(10, Math.min(500, p.x)), y: Math.max(40, Math.min(H - 20, p.y)) };
  } else if (dragTarget.kind === 'P') {
    np = projectOnLine(p, Pline.a, Pline.b);
    dirs[dragTarget.i] = sub(np, O);
  } else {
    np = projectOnLine(p, Qline.a, Qline.b);
    dirs[dragTarget.i] = sub(np, O);
  }
  update(currentStep === 3);
});
window.addEventListener('pointerup', function () { dragTarget = null; });

/* ---------- demo steps ---------- */
var steps = [
  { title: 'Read the three cross-ratios',
    narration: 'Three transversal lines cut the four rays from O at point sets P, Q, and R. Read the displayed cross-ratio of each set: all three numbers are identical.' },
  { title: 'Drag a point along its line',
    narration: 'Slide Q3 along the magenta Q-line: every set\'s cross-ratio updates live, and the three values stay equal at every instant. The invariant is the equality, not any particular number.' },
  { title: 'Move the center O',
    narration: 'Now drag O itself. All four rays swing, all twelve intersection points move, and still the three cross-ratios agree — the invariance does not depend on where the projection is taken from.' },
  { title: 'The point at infinity',
    narration: 'R1 → ∞: the R-line is parallel to the ray through P1 and Q1, so R1 escapes to infinity. Cross-ratio still works (its distance terms cancel), which is why this tool handles vanishing points in a single image.' }
];
var currentStep = 0;
function setStep(i) {
  currentStep = Math.max(0, Math.min(steps.length - 1, i));
  document.getElementById('demoNarration').textContent = steps[currentStep].narration;
  document.getElementById('stepLabel').textContent = (currentStep + 1) + ' / ' + steps.length;
  update(currentStep === 3);
}
function nextStep() { setStep(currentStep + 1); }
function prevStep() { setStep(currentStep - 1); }

build();
setStep(0);
window.__markRendered();
// @FIGURE_CODE_END

Fix all identified failure modes and improve every score. Maintain or improve what already works well.
Return ONLY the updated marker-wrapped payload.

userContent.text:
Build an interactive figure using SVG.js.

CONCEPT: The cross-ratio of four collinear points is preserved under any central projection, so all three sets (P, Q, R) share the same value no matter where the projection center O is or how the points slide along their lines.
KEY INSIGHT (what students should walk away understanding): Central projection preserves the cross-ratio of four collinear points — even when one point is at infinity — which is why cross-ratio lets a single image recover 3D structure that ordinary lengths and angles cannot.
DEMO STEPS: 4 guided steps — implement the step player in #ui

