var Qline = { a: { x: 285, y: 175 }, b: { x: 455, y: 590 } };   // steep diagonal down-right, middle
var Rpivot = { x: 340, y: 160 };                                // anchor near R4

function cross(u, v) { return u.x * v.y - u.y * v.x; }
function sub(a, b) { return { x: a.x - b.x, y: a.y - b.y }; }
function add(a, b) { return { x: a.x + b.x, y: a.y + b.y }; }
function mul(a, s) { return { x: a.x * s, y: a.y * s }; }
function norm(a) { var l = Math.hypot(a.x, a.y) || 1; return { x: a.x / l, y: a.y / l }; }

function rayLine(o, d, a, b) {
  var ab = sub(b, a), ao = sub(a, o);
  var den = cross(d, ab);
  if (Math.abs(den) < 1e-9) return null;
  var t = cross(ao, ab) / den;
  if (t <= 0) return null;
  return add(o, mul(d, t));
}
function lineParam(p, a, b) {
  var ab = sub(b, a);
  return ((p.x - a.x) * ab.x + (p.y - a.y) * ab.y) / (ab.x * ab.x + ab.y * ab.y);
}
function projectOnLine(p, a, b) {
  var t = lineParam(p, a, b);
  return add(a, mul(sub(b, a), t));
}
function safeCR(t1, t2, t3, t4) {
  var den = (t3 - t2) * (t4 - t1);
  if (Math.abs(den) < 1e-12) return NaN;
  return ((t3 - t1) * (t4 - t2)) / den;
}

/* ---------- layers ---------- */
var gRays = draw.group(), gLines = draw.group(), gPts = draw.group(), gLab = draw.group();

var rayEls = [], ptEls = { P: [], Q: [], R: [] }, labEls = { P: [], Q: [], R: [] };
var plineEl, qlineEl, rlineEl, oEl, oLab, infLab, infArrow;
var crTexts = [], crVals = [];   // direct tspan refs for live values

function serifText(size) {
  return draw.text('').font({ family: 'Georgia, "Times New Roman", serif', size: size, weight: 'bold' })
    .attr({ 'paint-order': 'stroke', stroke: '#fff', 'stroke-width': 4, 'stroke-linejoin': 'round' });
}
function labelWithSub(base, sub_) {
  var t = serifText(26);
  t.tspan(base);
  t.tspan(sub_).font({ size: 17 }).attr('dy', 7);
