}

function build() {
  var i;
  for (i = 0; i < 4; i++) rayEls.push(gRays.line(0, 0, 1, 1).stroke({ color: BLACK, width: 2.5 }));
  plineEl = gLines.line(0, 0, 1, 1).stroke({ color: MAGENTA, width: 3.5 });
