  rlineEl = gLines.line(0, 0, 1, 1).stroke({ color: MAGENTA, width: 3.5 });

  function mkDot(r, tip, setName) {
    var c = gPts.circle(r * 2).fill(BLACK).css('cursor', 'grab');
    c.on('mousemove', function (e) { showTooltip(tip, e); })
     .on('mouseleave', function () { hideTooltip(); })
     .on('click', function () {
       showPopup('Cross-ratio', 'Sliding this point along the ' + setName +
         '-line changes every set\'s cross-ratio at once — the three displayed values move together and always stay equal.');
     });
    return c;
  }
  for (i = 0; i < 4; i++) {
    ptEls.P.push(mkDot(11, 'P' + (i + 1) + ' — drag along the P-line', 'P'));
    ptEls.Q.push(mkDot(11, 'Q' + (i + 1) + ' — drag along the Q-line', 'Q'));
    ptEls.R.push(mkDot(11, i === 0 ? 'R1 → ∞ (ray ∥ R-line)' : 'R' + (i + 1) + ' = ray ' + (i + 1) + ' ∩ R-line', 'R'));
