    labEls.Q.push(labelWithSub('Q', String(i + 1)));
    labEls.R.push(labelWithSub('R', String(i + 1)));
  }
  oEl = gPts.circle(20).fill(BLACK).css('cursor', 'grab');
  oEl.on('mousemove', function (e) { showTooltip('O — projection center (drag me)', e); })
     .on('mouseleave', function () { hideTooltip(); })
     .on('click', function () {
       showPopup('Projection center', 'O is the center of projection. Moving it swings all four rays, yet the cross-ratio of each set P, Q, R is unchanged and identical — projection preserves cross-ratio.');
     });
  oLab = serifText(30); oLab.tspan('O');

  infLab = serifText(26);
  infLab.tspan('R');
  infLab.tspan('1').font({ size: 17 }).attr('dy', 7);
  infLab.tspan('→ ∞').font({ size: 24 }).attr('dy', -7);
  infArrow = gLab.line(0, 0, 1, 1).stroke({ color: BLACK, width: 2 });

  var names = ['CR(P₁,P₂,P₃,P₄)', 'CR(Q₁,Q₂,Q₃,Q₄)', 'CR(R₁,R₂,R₃,R₄)'];
  for (i = 0; i < 3; i++) {
    var t = draw.text('').font({ family: 'Georgia, serif', size: 18 })
      .attr({ 'paint-order': 'stroke', stroke: '#fff', 'stroke-width': 5, 'stroke-linejoin': 'round' })
      .move(14, 10 + i * 26);
    t.tspan(names[i] + ' = ').fill(BLACK);
    // store a DIRECT reference to the value tspan
    crVals.push(t.tspan('–').fill(MAGENTA).font({ weight: 'bold' }));
    crTexts.push(t);
  }

  /* ---- drag wiring ---- */
  ptEls.P.forEach(function (c, i) {
    c.on('pointerdown', function (e) { dragTarget = { kind: 'P', i: i }; e.preventDefault(); });
  });
  ptEls.Q.forEach(function (c, i) {
    c.on('pointerdown', function (e) { dragTarget = { kind: 'Q', i: i }; e.preventDefault(); });
  });
  oEl.on('pointerdown', function (e) { dragTarget = { kind: 'O' }; e.preventDefault(); });
}

function update(highlightInf) {
  var i;
  var rdir = norm(dirs[0]);                       // R-line ∥ lowest ray
  var Ra = sub(Rpivot, mul(rdir, 170)), Rb = add(Rpivot, mul(rdir, 620));

  plineEl.plot(Pline.a.x, Pline.a.y, Pline.b.x, Pline.b.y);
  qlineEl.plot(Qline.a.x, Qline.a.y, Qline.b.x, Qline.b.y);
  rlineEl.plot(Ra.x, Ra.y, Rb.x, Rb.y);

  for (i = 0; i < 4; i++) {
    var e = add(O, mul(dirs[i], 1600));
    rayEls[i].plot(O.x, O.y, e.x, e.y);
  }

  var P = [], Q = [], R = [];
  for (i = 0; i < 4; i++) {
    P.push(rayLine(O, dirs[i], Pline.a, Pline.b) || { x: -9999, y: -9999 });
    Q.push(rayLine(O, dirs[i], Qline.a, Qline.b) || { x: -9999, y: -9999 });
    R.push(i === 0 ? null : (rayLine(O, dirs[i], Ra, Rb) || { x: -9999, y: -9999 }));
  }
  oEl.center(O.x, O.y);
  oLab.move(O.x - 40, O.y - 14);

  // label offsets (dx, dy from dot center) tuned to sit in open space, like the source
  var labOffP = [[16, 4], [16, 0], [16, -6], [16, -14]];
  var labOffQ = [[10, 6], [14, 4], [14, 0], [10, -4]];
  var labOffR = [[0, 0], [-10, -52], [-12, -54], [-34, -44]];
  for (i = 0; i < 4; i++) {
    ptEls.P[i].center(P[i].x, P[i].y);
    ptEls.Q[i].center(Q[i].x, Q[i].y);
    labEls.P[i].move(P[i].x + labOffP[i][0], P[i].y + labOffP[i][1]);
    labEls.Q[i].move(Q[i].x + labOffQ[i][0], Q[i].y + labOffQ[i][1]);
    if (R[i]) {
      ptEls.R[i].center(R[i].x, R[i].y).show();
      labEls.R[i].move(R[i].x + labOffR[i][0], R[i].y + labOffR[i][1]).show();
    } else {
      ptEls.R[i].hide(); labEls.R[i].hide();
    }
  }

  // R1 → ∞ annotation at far right along the lowest ray, just past the R-line
  var inf = add(O, mul(rdir, 745));
  infLab.move(inf.x - 12, inf.y - 40).fill(highlightInf ? MAGENTA : BLACK);
  var arrowFrom = add(O, mul(rdir, 700)), arrowTo = add(O, mul(rdir, 735));
  infArrow.plot(arrowFrom.x, arrowFrom.y - 18, arrowTo.x, arrowTo.y - 10)
    .stroke({ color: highlightInf ? MAGENTA : BLACK });

  // cross-ratios (parameter along each line)
  function ts(pts, a, b) { return pts.map(function (p) { return lineParam(p, a, b); }); }
  var tP = ts(P, Pline.a, Pline.b), tQ = ts(Q, Qline.a, Qline.b);
  var tR = ts([R[1], R[2], R[3]], Ra, Rb);
  var crP = safeCR(tP[0], tP[1], tP[2], tP[3]);
  var crQ = safeCR(tQ[0], tQ[1], tQ[2], tQ[3]);
  // R1 at ∞: CR = (t4 − t2)/(t3 − t2)
  var den = tR[1] - tR[0];
  var crR = Math.abs(den) < 1e-12 ? NaN : (tR[2] - tR[0]) / den;

  function fmt(v) { return isFinite(v) ? v.toFixed(4) : '—'; }
  crVals[0].text(fmt(crP));
  crVals[1].text(fmt(crQ));
  crVals[2].text(fmt(crR));
}

/* ---------- dragging ---------- */
var dragTarget = null;
function svgPoint(ev) {
  var pt = draw.node.createSVGPoint();
  pt.x = ev.clientX; pt.y = ev.clientY;
  var m = draw.node.getScreenCTM();
  return m ? pt.matrixTransform(m.inverse()) : { x: pt.x, y: pt.y };
}
window.addEventListener('pointermove', function (e) {
  if (!dragTarget) return;
  var p = svgPoint(e), np, d;
  if (dragTarget.kind === 'O') {
    O = { x: Math.max(15, Math.min(430, p.x)), y: Math.max(70, Math.min(H - 30, p.y)) };
  } else if (dragTarget.kind === 'P') {
    np = projectOnLine(p, Pline.a, Pline.b);
    d = sub(np, O);
    if (Math.hypot(d.x, d.y) > 30) dirs[dragTarget.i] = d;
  } else {
    np = projectOnLine(p, Qline.a, Qline.b);
    d = sub(np, O);
    if (Math.hypot(d.x, d.y) > 30) dirs[dragTarget.i] = d;
  }
  update(currentStep === 3);
});
window.addEventListener('pointerup', function () { dragTarget = null; });

/* ---------- demo steps ---------- */
var steps = [
  { narration: 'Three transversal lines cut the four rays from O at point sets P, Q, and R. Read the displayed cross-ratio of each set: all three numbers are identical.' },
  { narration: 'Slide Q3 along the magenta Q-line: every set\'s cross-ratio updates live, and the three values stay equal at every instant. The invariant is the equality, not any particular number.' },
  { narration: 'Now drag O itself. All four rays swing, all twelve intersection points move, and still the three cross-ratios agree — the invariance does not depend on where the projection is taken from.' },
  { narration: 'R1 → ∞: the R-line is parallel to the ray through P1 and Q1, so R1 escapes to infinity. Cross-ratio still works (its distance terms cancel), which is why this tool handles vanishing points in a single image.' }
];
var currentStep = 0;
function setStep(i) {
  currentStep = Math.max(0, Math.min(steps.length - 1, i));
  document.getElementById('demoNarration').textContent = steps[currentStep].narration;
  document.getElementById('stepLabel').textContent = (currentStep + 1) + ' / ' + steps.length;
  update(currentStep === 3);
}
function nextStep() { setStep(currentStep + 1); }
function prevStep() { setStep(currentStep - 1); }

build();
setStep(0);
window.__markRendered();
// @FIGURE_CODE_END

